import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Backup and recovery","description":"","frontmatter":{"pageId":"admins/backup-recovery","contentRevision":1},"headers":[],"relativePath":"en/admins/backup-recovery.md","filePath":"en/admins/backup-recovery.md"}'),o={name:"en/admins/backup-recovery.md"};function i(n,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="backup-and-recovery" tabindex="-1">Backup and recovery <a class="header-anchor" href="#backup-and-recovery" aria-label="Permalink to &quot;Backup and recovery&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Use a consistent database-and-saves backup. Online backup: <code>rimlink-tools backup --data &lt;DataDir&gt; --out &lt;backup.tar.zst&gt;</code>; without --out it goes under backups. POST /api/admin/backups creates one, GET /backups lists them, GET /backups/{name} downloads one. Automatic defaults are Backup:IntervalHours=24 and Keep=7.</p><p>Before restoring, stop the server, preserve the current directory separately and test the selected backup in isolation. <code>rimlink-tools restore --data &lt;DataDir&gt; --from &lt;backup.tar.zst&gt;</code> replaces database and saves. After startup check /health, save versions, login and unfinished deliveries. Do not connect real players to a test restore.</p><p>admin rollback for one player is not whole-server recovery. Coordinate it with escrow state and client recovery journals.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Never delete save-storage.lock: the tool holds it with the storage lock through snapshot/packing. Older versions are not necessarily full .rws.zst files: they may be deltas. Test restorability, not just archive existence.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./updating">Updating server and clients</a></li><li><a href="./../developers/storage">Storage and escrow</a></li><li><a href="./../players/saves-recovery">Saves and recovery</a></li></ul>',10)])])}const k=a(o,[["render",i]]);export{h as __pageData,k as default};
